import{_ as t,o as d,c as o,a3 as i}from"./chunks/framework.vDgOMd_y.js";const m=JSON.parse('{"title":"kimi acp Subcommand","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/kimi-acp.md","filePath":"en/reference/kimi-acp.md"}'),a={name:"en/reference/kimi-acp.md"};function s(c,e,r,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/reference/kimi-acp.md for this page in Markdown format</div><h1 id="kimi-acp-subcommand" tabindex="-1"><code>kimi acp</code> Subcommand <a class="header-anchor" href="#kimi-acp-subcommand" aria-label="Permalink to &quot;`kimi acp` Subcommand&quot;">​</a></h1><p><code>kimi acp</code> switches Kimi Code CLI to <strong>ACP (Agent Client Protocol)</strong> mode: it communicates with an ACP client (such as Zed, JetBrains AI Chat, etc.) via JSON-RPC over stdin/stdout, letting the IDE directly drive kimi&#39;s sessions, prompts, and tool calls.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acp</span></span></code></pre></div><p>Once started, the command prints no banner and immediately waits for the ACP client to send an <code>initialize</code> request on stdin. Logs are written to stderr (as well as the diagnostic log under <code>~/.kimi-code/logs/</code>), so the ACP channel itself stays clean.</p><div class="tip custom-block"><p class="custom-block-title">Who calls this?</p><p>You typically do not need to run <code>kimi acp</code> manually — this command is the subprocess entry point for IDEs. For IDE-side configuration, see <a href="./../guides/ides.html">Using in IDEs</a>.</p></div><h2 id="capability-matrix" tabindex="-1">Capability Matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability Matrix&quot;">​</a></h2><p>The table below lists the capabilities declared by the current ACP adapter layer. The <code>agentCapabilities</code> field is returned in full in the <code>initialize</code> response, so the IDE can adjust its UI accordingly.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>promptCapabilities.image</code></td><td><code>true</code></td><td>Supports ACP <code>image</code> content blocks (base64 + mimeType)</td></tr><tr><td><code>promptCapabilities.audio</code></td><td><code>false</code></td><td>Audio prompts not yet supported</td></tr><tr><td><code>promptCapabilities.embeddedContext</code></td><td><code>true</code></td><td>Client may send <code>resource</code>/<code>resource_link</code> embedded resource blocks; text content is injected into the prompt as <code>&lt;resource uri=&quot;...&quot;&gt;...&lt;/resource&gt;</code>; blob resources are dropped with a warn</td></tr><tr><td><code>mcpCapabilities.http</code></td><td><code>true</code></td><td>Forwards HTTP MCP services configured by the IDE</td></tr><tr><td><code>mcpCapabilities.sse</code></td><td><code>true</code></td><td>Forwards legacy SSE MCP services configured by the IDE</td></tr><tr><td><code>loadSession</code></td><td><code>true</code></td><td>Supports <code>session/load</code> to resume an existing session, replaying history on load</td></tr><tr><td><code>sessionCapabilities.list</code></td><td><code>{}</code></td><td>Supports <code>session/list</code> to enumerate the current user&#39;s sessions</td></tr></tbody></table><h2 id="acp-method-coverage" tabindex="-1">ACP Method Coverage <a class="header-anchor" href="#acp-method-coverage" aria-label="Permalink to &quot;ACP Method Coverage&quot;">​</a></h2><p>The spec divides methods into a <strong>stable</strong> surface and an evolving <strong>unstable</strong> surface (handlers mounted with the <code>unstable_*</code> prefix in <code>@agentclientprotocol/sdk@0.23.0</code>). The two have entirely different stability guarantees — the stable surface covers methods every production ACP client uses, while the unstable surface covers experimental extensions (inline-edit prediction, document buffer sync, provider management, elicitation, etc.) — so they are tracked separately.</p><p><strong>Summary: stable agent-side 10/12 (83%) + client reverse-RPC 4/9 (44%); unstable surface has only <code>session/set_model</code> (1/19).</strong> All methods needed for a normal agent flow (initialize → auth → new/load/resume → prompt → cancel + file I/O + tool approval) are implemented.</p><h3 id="stable-agent-side-—-ide-→-agent-10-12" tabindex="-1">Stable agent-side — IDE → agent (10 / 12) <a class="header-anchor" href="#stable-agent-side-—-ide-→-agent-10-12" aria-label="Permalink to &quot;Stable agent-side — IDE → agent (10 / 12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Implemented</th><th>Description</th></tr></thead><tbody><tr><td><code>initialize</code></td><td>Yes</td><td>Version negotiation; returns <code>agentInfo: { name: &#39;Kimi Code CLI&#39;, version }</code>, capability matrix, and <code>authMethods</code></td></tr><tr><td><code>authenticate</code></td><td>Yes</td><td>Validates <code>method_id=&#39;login&#39;</code>; returns <code>authRequired (-32000)</code> if token is missing, <code>invalidParams (-32602)</code> for unknown ID</td></tr><tr><td><code>session/new</code></td><td>Yes</td><td>Accepts <code>cwd</code> / <code>mcpServers</code>; returns <code>configOptions[]</code></td></tr><tr><td><code>session/load</code></td><td>Yes</td><td>Restores a session from disk and replays history via <code>session/update</code></td></tr><tr><td><code>session/resume</code></td><td>Yes</td><td>Lightweight sibling of <code>session/load</code>; skips history replay</td></tr><tr><td><code>session/prompt</code></td><td>Yes</td><td>Accepts <code>text</code> / <code>image</code> / <code>resource</code> / <code>resource_link</code> content blocks; streams <code>agent_message_chunk</code></td></tr><tr><td><code>session/cancel</code></td><td>Yes</td><td>Interrupts the current turn</td></tr><tr><td><code>session/list</code></td><td>Yes</td><td>Enumerates sessions on disk (advertised via <code>sessionCapabilities.list = {}</code>)</td></tr><tr><td><code>session/set_mode</code></td><td>Yes</td><td>Compatibility path; dispatches to the same handler as <code>set_config_option({configId:&#39;mode&#39;})</code></td></tr><tr><td><code>session/set_config_option</code></td><td>Yes</td><td>Unified model / thinking / mode picker dispatcher</td></tr><tr><td><code>session/close</code></td><td>No</td><td></td></tr><tr><td><code>logout</code></td><td>No</td><td></td></tr></tbody></table><h3 id="stable-client-side-reverse-rpc-—-agent-→-ide-4-9" tabindex="-1">Stable client-side reverse-RPC — agent → IDE (4 / 9) <a class="header-anchor" href="#stable-client-side-reverse-rpc-—-agent-→-ide-4-9" aria-label="Permalink to &quot;Stable client-side reverse-RPC — agent → IDE (4 / 9)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Implemented</th><th>Description</th></tr></thead><tbody><tr><td><code>session/update</code></td><td>Yes</td><td>Streams <code>agent_message_chunk</code> / <code>tool_call*</code> / <code>plan</code> / <code>config_option_update</code> / <code>available_commands_update</code></td></tr><tr><td><code>session/request_permission</code></td><td>Yes</td><td>Shared channel for tool approval and question elicitation</td></tr><tr><td><code>fs/read_text_file</code></td><td>Yes</td><td>File reads at the kaos layer are routed to the client (advertised via <code>fsCapabilities</code>)</td></tr><tr><td><code>fs/write_text_file</code></td><td>Yes</td><td>File writes at the kaos layer are routed to the client</td></tr><tr><td><code>terminal/create</code> · <code>output</code> · <code>release</code> · <code>kill</code> · <code>wait_for_exit</code></td><td>No</td><td>Terminal reverse-RPC not connected; shell commands use local execution</td></tr></tbody></table><h3 id="unstable-surface-1-19" tabindex="-1">Unstable surface (1 / 19) <a class="header-anchor" href="#unstable-surface-1-19" aria-label="Permalink to &quot;Unstable surface (1 / 19)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Implemented</th><th>Description</th></tr></thead><tbody><tr><td><code>session/set_model</code></td><td>Yes</td><td>Compatibility path; equivalent to <code>set_config_option({configId:&#39;model&#39;})</code></td></tr><tr><td>Remaining 18 methods</td><td>No</td><td>Includes session lifecycle extensions, buffer sync, inline-edit prediction, provider management, etc.</td></tr></tbody></table><p>All methods not listed above return <code>methodNotFound</code>.</p><h2 id="mcp-forwarding" tabindex="-1">MCP Forwarding <a class="header-anchor" href="#mcp-forwarding" aria-label="Permalink to &quot;MCP Forwarding&quot;">​</a></h2><p>When an ACP client provides <code>mcpServers</code> in <code>session/new</code> or <code>session/load</code>, the adapter layer performs the following conversions:</p><ul><li><code>http</code> → kimi&#39;s <code>transport: &#39;http&#39;</code> configuration</li><li><code>stdio</code> → kimi&#39;s <code>transport: &#39;stdio&#39;</code> configuration</li><li><code>sse</code> → kimi&#39;s <code>transport: &#39;sse&#39;</code> configuration</li><li><code>acp</code> → discarded with a warn log entry</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../guides/ides.html">Using in IDEs</a> — Zed / JetBrains configuration steps and troubleshooting</li><li><a href="./kimi-command.html"><code>kimi</code> Command Reference</a> — Complete subcommand list</li></ul>',24)])])}const u=t(a,[["render",s]]);export{m as __pageData,u as default};
